head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[$p > M > log]<br/>WebSquare 로그 시스템에 메시지를 기록합니다.",
    "validation" : [
        "WebSquare 로그 시스템에 메시지를 기록해야 합니다.",
        "message(필수) 파라미터로 출력할 로그 메시지를 설정할 수 있어야 합니다.",
        "로그는 '웹스퀘어 로그 뷰어' 와 '브라우저 개발자 도구(Console)' 두 가지 방법으로 확인할 수 있어야 합니다.",
        "웹스퀘어 로그 뷰어는 브라우저에서 Ctrl 키를 누른 상태에서 마우스 오른쪽 버튼을 클릭해 노출되는 컨텍스트 메뉴의 '로그 보기' 를 통해 팝업되어야 합니다.",
        "로그 뷰어는 HTML 태그 textarea 로 구현되어 있으므로, 출력 대상이 객체 유형일 경우 '[object Object]' 와 같은 문자열로 출력되거나 오류가 발생할 수 있어야 합니다.",
        "브라우저 개발자 도구의 콘솔에서 로그를 확인하려면 config.xml 의 debug/console/@value 값이 'true' 로 설정되어 있어야 합니다.",

    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 초기 시나리오에 해당하는 message 기본값 반영
    var initScenario = par_scenario.getValue();
    if (Object.prototype.hasOwnProperty.call(scwin.scenarioMsgMap, initScenario)) {
        par_message.setValue(scwin.scenarioMsgMap[initScenario]);
    }
};



// 시나리오별 기본 message 값 (par_message input 에 자동 반영)
scwin.scenarioMsgMap = {
    "1" : "Log Test",
    "2" : "긴 문자열 로그 메시지 - WebSquare 로그 시스템은 긴 문자열도 그대로 기록합니다. 로그 뷰어(textarea)와 브라우저 콘솔에서 모두 동일한 내용으로 확인 가능해야 합니다.",
    "3" : "[object Object]"
};

scwin.par_scenario_onviewchange = function (e) {
    var val = par_scenario.getValue();
    if (Object.prototype.hasOwnProperty.call(scwin.scenarioMsgMap, val)) {
        par_message.setValue(scwin.scenarioMsgMap[val]);
    }
};



scwin.btn_log_onclick = function () {
    var scenario = par_scenario.getValue();
    var msgInput = par_message.getValue();

    if (scenario === "1") {
        // 일반 문자열 로그 (가이드 예시: $p.log('Log Test'))
        var msg = msgInput;
        wf_body_bottom.getObj("scwin").setReturnValue("$p.log('" + msg + "') 호출 완료");
    } else if (scenario === "2") {
        // 긴 문자열 로그
        var msg = msgInput;
        $p.log(msg);
        wf_body_bottom.getObj("scwin").setReturnValue("$p.log(긴 문자열) 호출 완료");        
    } else if (scenario === "3") {
        // 객체 타입 로그 - 로그 뷰어(textarea)에서는 '[object Object]' 로 출력
        var obj = { "a" : 1, "b" : "test", "nested" : { "x" : true } };
        $p.log(obj);        
        wf_body_bottom.getObj("scwin").setReturnValue("$p.log(object) 호출 완료");
    }
}
